async fn purchase_content_access_for_id(
    state: SharedState,
    headers: HeaderMap,
    content_id: String,
) -> AppResult<Json<ContentPurchase>> {
    let identity = require_identity(&state.pool, &headers).await?;
    enforce_rate_limit(
        &state,
        &format!("purchase-upload:{}", identity.user_id),
        20,
        Duration::from_secs(60),
    )
    .await?;
    let target = fetch_upload_playback_target(&state.pool, &content_id).await?;
    let terms = resolve_upload_access_terms(
        Some(target.upload.access_policy.clone()),
        target.upload.access_tier_id.clone(),
        target.upload.price_cents,
        target.upload.currency.clone(),
        target.upload.rental_window_hours,
    )?;
    if terms.access_policy != "purchase" && terms.access_policy != "subscription_or_purchase" {
        return Err(AppError::BadRequest(
            "content is not configured for direct purchase".to_string(),
        ));
    }
    ensure_creator_can_accept_paid_transactions(&state.pool, &target.creator_id).await?;
    if let Some(existing_purchase) =
        fetch_current_content_purchase(&state.pool, &identity.user_id, &target.upload.id).await?
    {
        return Ok(Json(existing_purchase));
    }
    let now = Utc::now();
    let purchased_at = now.to_rfc3339();
    let expires_at = terms
        .rental_window_hours
        .map(|hours| (now + chrono::Duration::hours(hours)).to_rfc3339());
    let purchase_id = format!("pur-{}", Uuid::new_v4().simple());

    sqlx::query(
        r#"
        INSERT INTO content_purchases (
            id, user_id, creator_id, upload_id, access_policy, amount_cents, currency,
            status, purchased_at, expires_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)
        "#,
    )
    .bind(&purchase_id)
    .bind(&identity.user_id)
    .bind(&target.creator_id)
    .bind(&target.upload.id)
    .bind(&terms.access_policy)
    .bind(terms.price_cents.unwrap_or_default())
    .bind(terms.currency.clone().unwrap_or_else(|| "USD".to_string()))
    .bind(&purchased_at)
    .bind(expires_at)
    .execute(&state.pool)
    .await?;
    let buyer = fetch_user(&state.pool, &identity.user_id).await?;
    enqueue_notification_event(
        &state.pool,
        "content_purchase",
        &format!("{} purchased {}.", buyer.display_name, target.upload.title),
        Some(&identity.user_id),
        Some(&buyer.display_name),
        Some(&target.creator_id),
        None,
        Some(terms.price_cents.unwrap_or_default() as f64 / 100.0),
        json!({
            "purchaseId": purchase_id,
            "uploadId": target.upload.id,
            "accessPolicy": terms.access_policy,
        }),
        &[],
        &[target.creator_id.clone()],
    )
    .await?;

    Ok(Json(
        fetch_content_purchase_by_id(&state.pool, &purchase_id).await?,
    ))
}

async fn subscribe_to_creator_tier(
    State(state): State<SharedState>,
    headers: HeaderMap,
    Path((creator_id, tier_id)): Path<(String, String)>,
) -> AppResult<Json<CreatorMembership>> {
    let identity = require_identity(&state.pool, &headers).await?;
    enforce_rate_limit(
        &state,
        &format!("creator-subscription:{}", identity.user_id),
        12,
        Duration::from_secs(60),
    )
    .await?;
    ensure_creator_can_accept_paid_transactions(&state.pool, &creator_id).await?;
    let tier = fetch_creator_subscriber_tier_by_id(&state.pool, &creator_id, &tier_id).await?;
    if tier.status != "active" {
        return Err(AppError::BadRequest(
            "subscriber tier is not available for new subscriptions".to_string(),
        ));
    }
    let now = Utc::now();
    let started_at = now.to_rfc3339();
    let renews_at = (now + chrono::Duration::days(30)).to_rfc3339();

    sqlx::query(
        r#"
        INSERT INTO creator_memberships (
            user_id, creator_id, tier_id, status, started_at, renews_at, ends_at, canceled_at
        ) VALUES (?, ?, ?, 'active', ?, ?, NULL, NULL)
        ON CONFLICT(user_id, creator_id) DO UPDATE SET
            tier_id = excluded.tier_id,
            status = 'active',
            started_at = excluded.started_at,
            renews_at = excluded.renews_at,
            ends_at = NULL,
            canceled_at = NULL
        "#,
    )
    .bind(&identity.user_id)
    .bind(&creator_id)
    .bind(&tier.id)
    .bind(&started_at)
    .bind(&renews_at)
    .execute(&state.pool)
    .await?;
    let subscriber = fetch_user(&state.pool, &identity.user_id).await?;
    enqueue_notification_event(
        &state.pool,
        "creator_subscription",
        &format!(
            "{} subscribed to {}.",
            subscriber.display_name, tier.tier_name
        ),
        Some(&identity.user_id),
        Some(&subscriber.display_name),
        Some(&creator_id),
        None,
        Some(tier.monthly_price),
        json!({
            "tierId": tier.id,
            "tierName": tier.tier_name,
            "membershipStartedAt": started_at,
        }),
        &[],
        &[creator_id.clone()],
    )
    .await?;

    Ok(Json(
        fetch_creator_membership(&state.pool, &identity.user_id, &creator_id).await?,
    ))
}

async fn cancel_creator_subscription(
    State(state): State<SharedState>,
    headers: HeaderMap,
    Path(creator_id): Path<String>,
) -> AppResult<StatusCode> {
    let identity = require_identity(&state.pool, &headers).await?;
    let now = Utc::now().to_rfc3339();
    let result = sqlx::query(
        r#"
        UPDATE creator_memberships
        SET status = 'canceling', canceled_at = ?, ends_at = COALESCE(ends_at, renews_at, ?)
        WHERE user_id = ? AND creator_id = ? AND status IN ('active', 'canceling')
        "#,
    )
    .bind(&now)
    .bind(&now)
    .bind(&identity.user_id)
    .bind(&creator_id)
    .execute(&state.pool)
    .await?;

    if result.rows_affected() == 0 {
        return Err(AppError::NotFound);
    }

    Ok(StatusCode::NO_CONTENT)
}

