async fn fetch_creator_live_socket_presence_by_id_raw(
    pool: &SqlitePool,
    creator_id: &str,
    socket_id: &str,
) -> AppResult<CreatorLiveSocketPresence> {
    let cutoff = active_presence_cutoff();
    let row = sqlx::query(
        r#"
        SELECT id, creator_id, user_id, connected_at, last_seen_at, disconnected_at
        FROM creator_live_socket_sessions
        WHERE creator_id = ? AND id = ?
        "#,
    )
    .bind(creator_id)
    .bind(socket_id)
    .fetch_optional(pool)
    .await?
    .ok_or(AppError::NotFound)?;

    let last_seen_at: String = row.get("last_seen_at");
    let disconnected_at: Option<String> = row.get("disconnected_at");
    Ok(CreatorLiveSocketPresence {
        id: row.get("id"),
        creator_id: row.get("creator_id"),
        user_id: row.get("user_id"),
        connected_at: row.get("connected_at"),
        last_seen_at: last_seen_at.clone(),
        disconnected_at,
        is_stale: last_seen_at < cutoff,
    })
}

async fn fetch_active_live_ingest_session(
    pool: &SqlitePool,
    creator_id: &str,
) -> AppResult<Option<LiveIngestSession>> {
    reconcile_stale_live_ingest_sessions_for_read(pool, Some(creator_id), None).await?;
    fetch_active_live_ingest_session_unreconciled(pool, creator_id).await
}

async fn fetch_active_live_ingest_session_unreconciled(
    pool: &SqlitePool,
    creator_id: &str,
) -> AppResult<Option<LiveIngestSession>> {
    let row = sqlx::query(
        r#"
        SELECT id, creator_id, broadcast_id, protocol, ingest_server, status, bitrate_kbps, viewers,
               dropped_frames, connected_at, last_heartbeat_at, disconnected_at
        FROM live_ingest_sessions
        WHERE creator_id = ? AND status = 'connected'
        ORDER BY connected_at DESC
        LIMIT 1
        "#,
    )
    .bind(creator_id)
    .fetch_optional(pool)
    .await?;

    row.map(live_ingest_session_from_row).transpose()
}

async fn count_live_ingest_sessions_for_broadcast(
    pool: &SqlitePool,
    creator_id: &str,
    broadcast_id: &str,
) -> AppResult<i64> {
    let row = sqlx::query(
        r#"
        SELECT COUNT(*) AS count
        FROM live_ingest_sessions
        WHERE creator_id = ? AND broadcast_id = ?
        "#,
    )
    .bind(creator_id)
    .bind(broadcast_id)
    .fetch_one(pool)
    .await?;
    Ok(row.get("count"))
}

