fn summarize_creator_analytics(analytics: &[AnalyticsPoint]) -> CreatorAnalyticsSummary {
    CreatorAnalyticsSummary {
        window_days: analytics.len() as i64,
        total_viewers: analytics.iter().map(|point| point.viewers).sum(),
        total_watch_minutes: analytics.iter().map(|point| point.watch_minutes).sum(),
        total_revenue: analytics.iter().map(|point| point.revenue).sum(),
        total_new_followers: analytics.iter().map(|point| point.new_followers).sum(),
    }
}

fn summarize_creator_revenue(
    analytics: &[AnalyticsPoint],
    revenue: &[RevenueEntry],
    subscriber_tiers: &[CreatorSubscriberTier],
) -> CreatorRevenueSummary {
    let total_subscribers = subscriber_tiers
        .iter()
        .map(|tier| tier.subscriber_count)
        .sum::<i64>();
    let weighted_price_total = subscriber_tiers
        .iter()
        .map(|tier| tier.monthly_price * tier.subscriber_count as f64)
        .sum::<f64>();
    let blended_monthly_price = if total_subscribers > 0 {
        weighted_price_total / total_subscribers as f64
    } else {
        0.0
    };

    let positive_total = revenue
        .iter()
        .filter(|entry| entry.amount > 0.0)
        .map(|entry| entry.amount)
        .sum::<f64>();
    let payout_total = revenue
        .iter()
        .filter(|entry| entry.source == "payout")
        .map(|entry| entry.amount.abs())
        .sum::<f64>();
    let total_earnings_30d = analytics.iter().map(|point| point.revenue).sum::<f64>();
    let estimated_next_payout = (total_earnings_30d - payout_total).max(0.0);

    let mut breakdown = Vec::new();
    for source in ["subscriptions", "ads", "tips", "clips", "payout"] {
        let amount = revenue
            .iter()
            .filter(|entry| entry.source == source && entry.amount > 0.0)
            .map(|entry| entry.amount)
            .sum::<f64>();
        let share = if positive_total > 0.0 {
            amount / positive_total
        } else {
            0.0
        };
        breakdown.push(CreatorRevenueBreakdownEntry {
            source: source.to_string(),
            amount,
            share,
        });
    }

    CreatorRevenueSummary {
        total_earnings_30d,
        total_subscribers,
        blended_monthly_price,
        estimated_next_payout,
        breakdown,
    }
}

async fn fetch_notifications_rows(
    pool: &SqlitePool,
    creator_id: &str,
) -> AppResult<Vec<CreatorNotification>> {
    reconcile_notification_deliveries_for_read(
        pool,
        None,
        None,
        Some(creator_id),
        None,
    )
    .await?;
    let legacy_rows = sqlx::query(
        "SELECT id, kind, body, sent_at, amount, actor FROM creator_notifications WHERE creator_id = ?",
    )
    .bind(creator_id)
    .fetch_all(pool)
    .await?;

    let delivery_rows = sqlx::query(
        r#"
        SELECT d.id, e.kind, e.body, d.sent_at, e.amount, e.actor_label, d.state, d.read_at
        FROM notification_deliveries d
        JOIN notification_events e ON e.id = d.event_id
        WHERE d.recipient_creator_id = ? AND d.channel = 'inbox'
        "#,
    )
    .bind(creator_id)
    .fetch_all(pool)
    .await?;

    let mut notifications: Vec<CreatorNotification> = legacy_rows
        .into_iter()
        .map(|row| CreatorNotification {
            id: row.get("id"),
            kind: row.get("kind"),
            body: row.get("body"),
            sent_at: row.get("sent_at"),
            amount: row.get("amount"),
            actor: row.get("actor"),
            delivery_state: None,
            read_at: None,
        })
        .collect();

    notifications.extend(delivery_rows.into_iter().map(|row| CreatorNotification {
        id: row.get("id"),
        kind: row.get("kind"),
        body: row.get("body"),
        sent_at: row.get("sent_at"),
        amount: row.get("amount"),
        actor: row.get("actor_label"),
        delivery_state: Some(row.get("state")),
        read_at: row.get("read_at"),
    }));

    notifications.sort_by(|a, b| b.sent_at.cmp(&a.sent_at));
    Ok(notifications)
}

