async fn fetch_continue_watching_entry(
    pool: &SqlitePool,
    user_id: &str,
    content_id: Option<&str>,
    slug_or_id: &str,
) -> AppResult<Option<ContinueWatchingEntry>> {
    let target_content_id = match content_id {
        Some(id) => id.to_string(),
        None => {
            if let Some(row) = sqlx::query("SELECT id FROM series WHERE slug = ?")
                .bind(slug_or_id)
                .fetch_optional(pool)
                .await?
            {
                row.get("id")
            } else if let Some(row) = sqlx::query("SELECT id FROM films WHERE slug = ?")
                .bind(slug_or_id)
                .fetch_optional(pool)
                .await?
            {
                row.get("id")
            } else {
                return Ok(None);
            }
        }
    };

    let row = sqlx::query(
        "SELECT content_id, kind, episode_id, progress_sec, duration_sec, last_watched_at FROM continue_watching WHERE user_id = ? AND content_id = ?",
    )
    .bind(user_id)
    .bind(target_content_id)
    .fetch_optional(pool)
    .await?;

    Ok(row.map(|item| ContinueWatchingEntry {
        content_id: item.get("content_id"),
        kind: item.get("kind"),
        episode_id: item.get("episode_id"),
        progress_sec: item.get("progress_sec"),
        duration_sec: item.get("duration_sec"),
        last_watched_at: item.get("last_watched_at"),
    }))
}

async fn upsert_watch_history_entry(
    pool: &SqlitePool,
    user_id: &str,
    content_id: &str,
    kind: &str,
    episode_id: Option<&str>,
    progress_sec: i64,
    duration_sec: i64,
    completed: bool,
    watched_at: &str,
) -> AppResult<()> {
    let completed_at = if completed {
        Some(watched_at.to_string())
    } else {
        None
    };
    sqlx::query(
        r#"
        INSERT INTO user_watch_history (
            user_id, content_id, kind, episode_id, progress_sec, duration_sec,
            completed, completed_at, last_watched_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(user_id, content_id) DO UPDATE SET
            kind = excluded.kind,
            episode_id = excluded.episode_id,
            progress_sec = excluded.progress_sec,
            duration_sec = excluded.duration_sec,
            completed = excluded.completed,
            completed_at = excluded.completed_at,
            last_watched_at = excluded.last_watched_at
        "#,
    )
    .bind(user_id)
    .bind(content_id)
    .bind(kind)
    .bind(episode_id)
    .bind(progress_sec)
    .bind(duration_sec)
    .bind(completed as i64)
    .bind(completed_at)
    .bind(watched_at)
    .execute(pool)
    .await?;
    Ok(())
}

fn streamer_from_row(row: sqlx::sqlite::SqliteRow) -> Streamer {
    Streamer {
        id: row.get("id"),
        handle: row.get("handle"),
        display_name: row.get("display_name"),
        avatar: row.get("avatar"),
        bio: row.get("bio"),
        followers: row.get("followers"),
        is_partner: row.get::<i64, _>("is_partner") == 1,
        is_live: row.get::<i64, _>("is_live") == 1,
    }
}

fn live_stream_from_row(row: sqlx::sqlite::SqliteRow) -> LiveStream {
    let playback_ready = row.get::<Option<String>, _>("playback_asset_id").is_some()
        && row
            .get::<Option<String>, _>("playback_relative_path")
            .is_some();
    LiveStream {
        id: row.get("id"),
        slug: row.get("slug"),
        title: row.get("title"),
        category: row.get("category"),
        tags: from_json(row.get::<String, _>("tags_json")).unwrap_or_default(),
        streamer: Streamer {
            id: row.get("streamer_id"),
            handle: row.get("handle"),
            display_name: row.get("display_name"),
            avatar: row.get("avatar"),
            bio: row.get("bio"),
            followers: row.get("followers"),
            is_partner: row.get::<i64, _>("is_partner") == 1,
            is_live: row.get::<i64, _>("is_live") == 1,
        },
        viewers: row.get("viewers"),
        started_at: row.get("started_at"),
        thumbnail: row.get("thumbnail"),
        language: row.get("language"),
        is_mature: row.get::<i64, _>("is_mature") == 1,
        kind: "live".to_string(),
        playback_session_url: playback_ready
            .then(|| playback_live_session_api_url(&row.get::<String, _>("id"))),
        playback_ready,
    }
}

