fn media_path_for_relative(state: &SharedState, relative_path: &str) -> std::path::PathBuf {
    state.media_root.join(relative_path)
}

async fn ensure_parent_dir(path: &std::path::Path) -> AppResult<()> {
    let parent = path.parent().ok_or_else(|| {
        AppError::BadRequest("invalid media path without parent directory".to_string())
    })?;
    tokio::fs::create_dir_all(parent).await?;
    Ok(())
}

async fn sha256_file(path: &std::path::Path) -> AppResult<String> {
    use tokio::io::AsyncReadExt;

    let mut file = tokio::fs::File::open(path).await?;
    let mut hasher = sha2::Sha256::new();
    let mut buffer = [0_u8; 64 * 1024];
    loop {
        let read = file.read(&mut buffer).await?;
        if read == 0 {
            break;
        }
        use sha2::Digest;
        hasher.update(&buffer[..read]);
    }
    Ok(format!("{:x}", hasher.finalize()))
}

fn sanitize_storage_key(input: &str) -> AppResult<String> {
    if input.is_empty() {
        return Err(AppError::BadRequest("storageKey is required".to_string()));
    }

    let mut normalized_parts = Vec::new();
    for component in std::path::Path::new(input).components() {
        match component {
            Component::Normal(part) => {
                let part = part
                    .to_str()
                    .ok_or_else(|| AppError::BadRequest("storageKey must be utf-8".to_string()))?;
                if part.trim().is_empty() {
                    return Err(AppError::BadRequest(
                        "storageKey contains an empty segment".to_string(),
                    ));
                }
                normalized_parts.push(part.to_string());
            }
            Component::CurDir => {}
            Component::ParentDir | Component::RootDir | Component::Prefix(_) => {
                return Err(AppError::BadRequest(
                    "storageKey must be a safe relative path".to_string(),
                ));
            }
        }
    }

    if normalized_parts.is_empty() {
        return Err(AppError::BadRequest(
            "storageKey must contain at least one path segment".to_string(),
        ));
    }

    Ok(normalized_parts.join("/"))
}

fn require_upload_token(headers: &HeaderMap) -> AppResult<String> {
    let value = headers
        .get("x-upload-token")
        .ok_or(AppError::Unauthorized)?
        .to_str()
        .map_err(|_| AppError::Unauthorized)?
        .trim()
        .to_string();

    if value.is_empty() {
        return Err(AppError::Unauthorized);
    }

    Ok(value)
}

fn require_ingest_token(headers: &HeaderMap) -> AppResult<String> {
    let value = headers
        .get("x-ingest-token")
        .ok_or(AppError::Unauthorized)?
        .to_str()
        .map_err(|_| AppError::Unauthorized)?
        .trim()
        .to_string();

    if value.is_empty() {
        return Err(AppError::Unauthorized);
    }

    Ok(value)
}

async fn validate_upload_ingest_token(
    pool: &SqlitePool,
    creator_id: &str,
    job_id: &str,
    upload_token: &str,
) -> AppResult<()> {
    let token_hash = crate::auth::hash_token(upload_token);
    let exists = sqlx::query(
        "SELECT 1 FROM upload_job_ingest_sessions WHERE creator_id = ? AND job_id = ? AND upload_token_hash = ?",
    )
    .bind(creator_id)
    .bind(job_id)
    .bind(token_hash)
    .fetch_optional(pool)
    .await?
    .is_some();

    if exists {
        Ok(())
    } else {
        Err(AppError::Unauthorized)
    }
}

