async fn validate_creator_access_tier(
    pool: &SqlitePool,
    creator_id: &str,
    access_policy: &str,
    access_tier_id: Option<&str>,
) -> AppResult<()> {
    if !matches!(access_policy, "subscription" | "subscription_or_purchase") {
        return Ok(());
    }
    let tier_id = access_tier_id.ok_or_else(|| {
        AppError::BadRequest(
            "subscription-based access requires an active subscriber tier".to_string(),
        )
    })?;
    let tier = fetch_creator_subscriber_tier_by_id(pool, creator_id, tier_id).await?;
    if tier.status != "active" {
        return Err(AppError::BadRequest(
            "subscription-based access requires an active subscriber tier".to_string(),
        ));
    }
    Ok(())
}

async fn ensure_creator_can_publish_paid_content(
    pool: &SqlitePool,
    creator_id: &str,
) -> AppResult<()> {
    let profile = fetch_creator_profile(pool, creator_id).await?;
    let state = fetch_creator_operational_state(pool, &profile).await?;
    if state.can_publish_paid_content {
        Ok(())
    } else {
        Err(AppError::BadRequest(
            "creator is not cleared to publish paid content".to_string(),
        ))
    }
}

async fn ensure_creator_can_accept_paid_transactions(
    pool: &SqlitePool,
    creator_id: &str,
) -> AppResult<()> {
    let profile = fetch_creator_profile(pool, creator_id).await?;
    let state = fetch_creator_operational_state(pool, &profile).await?;
    if state.can_receive_payouts {
        Ok(())
    } else {
        Err(AppError::BadRequest(
            "creator is not cleared to accept paid transactions".to_string(),
        ))
    }
}

fn from_json<T: serde::de::DeserializeOwned>(value: String) -> AppResult<T> {
    Ok(serde_json::from_str(&value)?)
}

fn to_json<T: serde::Serialize>(value: &T) -> AppResult<String> {
    Ok(serde_json::to_string(value)?)
}

fn build_fts_query(input: &str) -> Option<String> {
    let normalized = input
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' {
                ch.to_ascii_lowercase()
            } else {
                ' '
            }
        })
        .collect::<String>();

    let tokens = normalized
        .split_whitespace()
        .filter(|token| !token.is_empty())
        .take(6)
        .map(|token| format!("{token}*"))
        .collect::<Vec<_>>();

    if tokens.is_empty() {
        None
    } else {
        Some(tokens.join(" "))
    }
}

async fn enforce_rate_limit(
    state: &SharedState,
    key: &str,
    limit: usize,
    window: Duration,
) -> AppResult<()> {
    state
        .rate_limits
        .check(key, limit, window)
        .await
        .map_err(|_| {
            state.metrics.increment_rate_limit();
            AppError::RateLimited
        })
}

