    #[tokio::test]
    async fn expired_live_moderation_action_is_reported_expired_before_reconciliation(
    ) -> AppResult<()> {
        let (state, creator) = setup_test_state().await?;
        let token = insert_creator_auth_session(&state.pool, &creator).await?;
        let headers = auth_headers(&token);
        let stream_id = insert_live_stream_for_creator(&state.pool, &creator).await?;
        let action_id = format!("test-lma-{}", Uuid::new_v4().simple());
        let created_at = (Utc::now() - chrono::Duration::hours(1)).to_rfc3339();
        let expired_at = (Utc::now() - chrono::Duration::minutes(5)).to_rfc3339();
        sqlx::query(
            r#"
            INSERT INTO live_moderation_actions (
                id, stream_id, creator_id, subject_user_id, actor_user_id, action_type, reason,
                state, expires_at, created_at, revoked_at
            ) VALUES (?, ?, ?, ?, ?, 'mute', ?, 'active', ?, ?, NULL)
            "#,
        )
        .bind(&action_id)
        .bind(&stream_id)
        .bind(&creator.id)
        .bind("usr-2")
        .bind(&creator.user_id)
        .bind("expired moderation")
        .bind(&expired_at)
        .bind(&created_at)
        .execute(&state.pool)
        .await?;

        let by_id = fetch_live_moderation_action_by_id(&state.pool, &action_id).await?;
        let listed = list_live_moderation_actions(State(state.clone()), headers, Path(stream_id))
            .await?
            .0;
        let stored_state: String = sqlx::query("SELECT state FROM live_moderation_actions WHERE id = ?")
            .bind(&action_id)
            .fetch_one(&state.pool)
            .await?
            .get("state");

        assert_eq!(by_id.state, "expired");
        assert_eq!(stored_state, "expired");
        assert!(
            listed
                .iter()
                .any(|action| action.id == action_id && action.state == "expired")
        );
        Ok(())
    }

    #[tokio::test]
    async fn expired_live_moderation_lookup_self_heals_stored_state_and_active_gate()
    -> AppResult<()> {
        let (state, creator) = setup_test_state().await?;
        let stream_id = insert_live_stream_for_creator(&state.pool, &creator).await?;
        let action_id = format!("test-lma-{}", Uuid::new_v4().simple());
        let created_at = (Utc::now() - chrono::Duration::hours(1)).to_rfc3339();
        let expired_at = (Utc::now() - chrono::Duration::minutes(5)).to_rfc3339();
        sqlx::query(
            r#"
            INSERT INTO live_moderation_actions (
                id, stream_id, creator_id, subject_user_id, actor_user_id, action_type, reason,
                state, expires_at, created_at, revoked_at
            ) VALUES (?, ?, ?, ?, ?, 'mute', ?, 'active', ?, ?, NULL)
            "#,
        )
        .bind(&action_id)
        .bind(&stream_id)
        .bind(&creator.id)
        .bind("usr-2")
        .bind(&creator.user_id)
        .bind("expired moderation gate")
        .bind(&expired_at)
        .bind(&created_at)
        .execute(&state.pool)
        .await?;

        let active = fetch_active_live_moderation_action(&state.pool, &stream_id, "usr-2").await?;
        let stored = fetch_live_moderation_action_by_id(&state.pool, &action_id).await?;
        let audit = fetch_moderation_audit_log(&state.pool, &creator.id, Some(&stream_id)).await?;

        assert!(active.is_none());
        assert_eq!(stored.state, "expired");
        assert!(audit.iter().any(|entry| {
            entry.event_type == "moderation_action_expired"
                && entry.payload["actionId"] == Value::String(action_id.clone())
        }));
        Ok(())
    }

